          language: j.language || '', format: j.format || '',
          instructions: clip(j.instructions, 2000),
          family: j.family || '', quant: j.quant || '', model_path: clip(j.model_path, 500),
          file_path: j.file_path || '', transcript: clip(j.transcript, 8000), error: clip(j.error, 500),
          // Reference-window note (truncation-zone warning / force:true override).
          note: clip(j.note, 300),
          // The language decision survives a restart, so a row restored from the
