          voice_mode: VOICE_MODE_SET[j.voice_mode] ? String(j.voice_mode) : '',
          cost_per_second: typeof j.cost_per_second === 'number' && isFinite(j.cost_per_second) ? j.cost_per_second : 0,
          batch_id: typeof j.batch_id === 'string' ? j.batch_id.slice(0, 20) : '',
          batch_part: typeof j.batch_part === 'number' && isFinite(j.batch_part) ? j.batch_part : 0,
          batch_parts: typeof j.batch_parts === 'number' && isFinite(j.batch_parts) ? j.batch_parts : 0,
          batch_title: typeof j.batch_title === 'string' ? clip(j.batch_title, 120) : '',
          batch_cast: Array.isArray(j.batch_cast) ? j.batch_cast.slice(0, 8) : [],
