          // nothing to refuse it with.
          batch_retry_of: typeof j.batch_retry_of === 'string' ? j.batch_retry_of.slice(0, 24) : '',
          batch_retried_to: typeof j.batch_retried_to === 'string' ? j.batch_retried_to.slice(0, 24) : '',
          batch_halt: typeof j.batch_halt === 'string' ? clip(j.batch_halt, 300) : '',
          batch_wait_retry: typeof j.batch_wait_retry === 'string' ? clip(j.batch_wait_retry, 300) : '',
