  var PERF_FILE = BASE + '/perf_log.jsonl';
  var perfLogOn = true;
  function wordCount(s) {
    var t = String(s || '').trim();
    return t ? t.split(/\s+/).length : 0;
  }
  // An empty transcription answer is a failure. The 2026-10-26 measurement recorded in review/
  // live_round_20261026/FINDINGS_20261026.md is what settled it: a `dispatch_stt` press on canary_asr
  // answered `ok` with an EMPTY transcript and the row looked like a success. It is one verdict now,
