      ev: 'job_outcome',
      job: job.id, fn: job.fn, kind: job.kind || '',
      model: job.model || '', diar_model: job.diar_model || '', task_kind: job.task_kind || '',
      quant: job.quant || '', voice: job.voice || '',
      vc_target: job.vc_target_voice || '',
      endpoint_id: job.endpoint_id || '', ep: job.endpoint_url || '',
      host: job.host || hostKeyOf(job.endpoint_url || ''),
      st: job.status, cls: cls || '',
