        if (!v || typeof v !== 'object' || Array.isArray(v)) return null;
        var o = { speaker: clip(String(v.speaker == null ? '' : v.speaker), 40) };
        if (v.verdict) o.verdict = clip(String(v.verdict), 24);
        if (typeof v.expected_seconds === 'number' && isFinite(v.expected_seconds)) o.expected_seconds = Math.round(v.expected_seconds * 100) / 100;
        if (typeof v.heard_seconds === 'number' && isFinite(v.heard_seconds)) o.heard_seconds = Math.round(v.heard_seconds * 100) / 100;
        return o;
