                // feed is always 16 kHz mono here, so 16000 is the correct divisor.
                diarFinish(Array.isArray(p2 && p2.speaker_turns) ? p2.speaker_turns : [],
                  Number(p2 && p2.sample_rate) || 16000, '',
                  (p2 && p2.timing && p2.timing.audio_duration_ms) || 0);
