              // treated as within the ceiling (the engine would answer 413 if it were not), so a
              // failed stat never blocks a normal dispatch.
              if (feedBytes > DIAR_TASKS_MAX_FEED_BYTES) {
                perfLog({
                  ev: 'diar_knob_route', ep: endpoint.url, fn: 'stt', job: job.id, model: job.model,
                  via: 'refused_size', feed_bytes: feedBytes, ceiling_bytes: DIAR_TASKS_MAX_FEED_BYTES,
                  knobs: job.diar_options,
                });
                job.status = 'error';
                job.error = diarTasksCeilingRefusal(feedBytes, Object.keys(job.diar_options).join(', '));
                return;
              }
              perfLog({
                ev: 'diar_knob_route', ep: endpoint.url, fn: 'stt', job: job.id, model: job.model,
                via: 'tasks_run', feed_bytes: feedBytes, knobs: job.diar_options,
              });
