                speaker_id: tt.speaker_id != null ? String(tt.speaker_id).slice(0, 40) : '?',
                start: (Number(tt.start_sample) || 0) / asr,
                end: (Number(tt.end_sample) || 0) / asr,
                confidence: typeof tt.confidence === 'number' ? tt.confidence : undefined,
                text: typeof tt.text === 'string' ? String(tt.text).slice(0, 400) : undefined,
