              words: wordCount(job.transcript || ''), turns: (job.speaker_turns || []).length,
              in_bytes: bytesIn, ms: Date.now() - (job.started || Date.now()),
              // The perf line names which shape actually left this host for this take.
              feed_mode: (job.stt_feed || {}).mode || '', feed_rate: (job.stt_feed || {}).rate || 0,
