      var old596 = textPresetDoc596(txt596);
      if (!old596) {
        return { ok: false, path: p596, error: 'that file is not a preset this verb may rewrite — batch_text_update takes a preset (kind "preset"); a dialogue batch file is left to batch_text_save, which refuses to overwrite it' };
      }
