        // The rate this part ACTUALLY ran at, the seconds the split expected from
        // its own script slice, and the drift between them. Recorded, never fed back into the
        // split. 0 means "not measured", not "ran at zero".
        chars_per_sec: typeof j.chars_per_sec === 'number' ? j.chars_per_sec : 0,
        rate_source: j.rate_source || '',
        expected_seconds: typeof j.expected_seconds === 'number' ? j.expected_seconds : 0,
        est_drift: typeof j.est_drift === 'number' ? j.est_drift : 0,
        over_run: j.over_run === true,
