    // everything after the id goes through slug(), so only [a-z0-9-] survives.
    var fmt = body.format === 'mp3' || body.format === 'ogg' ? body.format : 'wav';
    var nameBase = id
      + (slug(body.model, 24) ? '_' + slug(body.model, 24) : '')
      + (slug(body.voice, 20) ? '_' + slug(body.voice, 20) : '')
      + (slug(body.text, 40) ? '_' + slug(body.text, 40) : '');
    var outPath = ttsDir + '/' + nameBase + '.wav';
