      family: raw ? (raw.family || '') : '',
      quant: raw ? quantOf(raw.path) : '',
      model_path: raw ? (raw.path || '') : '',
      format: fmt,
      created: Date.now(), queued_at: Date.now(), started: 0, ended: 0,
      activity: '', elapsed_load: 0, elapsed_gen: 0, duration: 0,
      wav_path: outPath, output_path: outPath,
