          if (!ssp) {
            logDispatchRefuse('dispatch_stt', fn, 'no stem ' + sst + ' on row ' + srcRow.id, { model: model, source_job_id: body.source_job_id });
            return Promise.resolve({ ok: false, error: 'no stem ' + sst + ' on row ' + srcRow.id });
          }
