      var seglst = null;
      var arts = Array.isArray(parsed.artifacts) ? parsed.artifacts : [];
      for (var ai = 0; ai < arts.length; ai++) {
        if (arts[ai] && arts[ai].id === 'seglst' && typeof arts[ai].payload === 'string') { seglst = arts[ai].payload; break; }
      }
