    if (Object.prototype.hasOwnProperty.call(diarOpts, 'return_frame_probabilities') && diarOpts.return_frame_probabilities !== true) {
      logDispatchRefuse('dispatch_speaker_asr', 'stt', 'return_frame_probabilities must be true on this route', { model: asrModel, diar_model: diarModel });
      return Promise.resolve({ ok: false, error: 'return_frame_probabilities must be true on dispatch_speaker_asr — the chain reads the speaker_probabilities.safetensors artifact it produces, and without it there is no second step' });
    }
