    var srcBase = String(audioPath).replace(/^.*\//, '').replace(/\.[A-Za-z0-9]+$/, '');
    var outPath = STT_DIR + '/' + id + '_' + (slug(asrModel, 24) || 'asr') + '_' + (slug(srcBase, 30) || 'audio') + '.txt';
    var job = {
      id: id, fn: 'stt', kind: 'sasr', status: 'queued',
      model: asrModel, diar_model: diarModel, file_path: audioPath,
      // The press's own intent, kept beside the resolved name. `diar_model` is what will run;
      // `diar_model_from_default` is whether the press asked for it or the plugin filled it in. Private to
      // the row (like `_waiters`): rowOf does not emit it, the chain record's marker does.
      diar_model_from_default: !body.diar_model,
      // This is honesty, not behaviour: on THIS lane the language rides inside
      // asr_options.language — nemotron_asr's own contract (model_specs/nemotron_asr.json:
      // "ASR prompt language such as en-US, da-DK, or auto") is enforced by
      // cleanSpeakerAsrOptions, which REFUSES a value that is not a BCP-47 tag rather than
      // omitting it. The row now carries the value that actually rides instead of a second
      // copy of whatever the caller typed.
      language: (asrOpts && asrOpts.language) || '',
      created: Date.now(), queued_at: Date.now(), started: 0, ended: 0,
      activity: '', elapsed_load: 0, elapsed_gen: 0, duration: 0,
      output_path: outPath, _waiters: [],
    };
    job.diar_options = diarOpts;
    job.asr_options = asrOpts;
    job.speaker_asr = {
      diar_model: diarModel, asr_model: asrModel,
      diar_options: diarOpts, asr_options: asrOpts, stage: 'queued',
    };
